"""Receipt refusals use bounded supplied software fixtures, not science panels."""
import copy
import unittest
from experiments.digital_ecosystem_audit import audit_world, h


class DigitalReceiptIntegrityTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        # The public summary contains no raw histories. Use a bounded software
        # fixture generated by the explicitly supplied ancestor.
        from experiments.digital_ecosystem import World
        cls.row=World(0,'faithful').run(64)
        cls.row['checkpoint_replay']=True

    def test_valid_finite_checkpoint_and_extinction_history(self):
        audit_world(self.row)
        from experiments.digital_ecosystem import World
        row=World(1,'faithful').run(256);row['checkpoint_replay']=True
        self.assertFalse(row['final']['entities'])
        audit_world(row)

    def test_continuation_identity_forgery_refused_even_with_rehashed_state(self):
        for key in ('tick','writes','last','next_id','births','deaths','max_population','seed'):
            with self.subTest(field=key):
                row=copy.deepcopy(self.row);row['final'][key]+=1;row['state_hash']=h(row['final'])
                with self.assertRaises(AssertionError):audit_world(row)

    def test_snapshot_mode_history_and_extra_fields_refused(self):
        for key,value in (('mode','mutating'),('events',[]),('unsupported_state',0)):
            with self.subTest(field=key):
                row=copy.deepcopy(self.row);row['final'][key]=value;row['state_hash']=h(row['final'])
                with self.assertRaises(AssertionError):audit_world(row)

    def test_boolean_integer_and_outcome_forgery_refused(self):
        row=copy.deepcopy(self.row);row['events'][0]['tick']=True
        with self.assertRaises(AssertionError):audit_world(row)
        row=copy.deepcopy(self.row);row['events'][0]['outcome']='division_refused'
        with self.assertRaises(AssertionError):audit_world(row)
        row=copy.deepcopy(self.row)
        next(e for e in row['events'] if 'write' in e)['write']['mutated']=0
        with self.assertRaises(AssertionError):audit_world(row)

    def test_scope_claim_and_checkpoint_flag_forgery_refused(self):
        for key,value in (('learning_demonstrated',True),('ancestor_supplied',False),('checkpoint_replay',1)):
            with self.subTest(field=key):
                row=copy.deepcopy(self.row);row[key]=value
                with self.assertRaises(AssertionError):audit_world(row)
